package com.pranit.helpdesk.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.Key; import java.util.Date;
@Service public class JwtService{private final Key key;private final long expiration;public JwtService(@Value("${jwt.secret}") String secret,@Value("${jwt.expiration:86400000}") long expiration){if(secret==null||secret.length()<32)throw new IllegalArgumentException("JWT secret must be at least 32 characters");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;}public String generate(String username,String role){return Jwts.builder().setSubject(username).claim("role",role).setIssuedAt(new Date()).setExpiration(new Date(System.currentTimeMillis()+expiration)).signWith(key).compact();}public String username(String token){return Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token).getBody().getSubject();}public boolean valid(String token){try{username(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}}}
